code.source:
class Animal:
    def __init__(self, name):
        self.name = name

    def eat(self):
        print(self.name, "is eating")

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)
        self.breed = breed

    def bark(self):
        print(self.name, "says Woof")

d = Dog("Rex", "Labrador")
d.eat()
d.bark()
print(d.breed)

